package main

import (
	"fmt"
	"log"
	"net"
	"sync"
	"time"
)

// DNSForwarder handles incoming DNS requests
type DNSForwarder struct {
	cache   map[string][]net.IP
	mu      sync.RWMutex
	upstream []string
}

// NewDNSForwarder creates a new instance
func NewDNSForwarder(upstreams []string) *DNSForwarder {
	return &DNSForwarder{
		cache:   make(map[string][]net.IP),
		upstream: upstreams,
	}
}

// Resolve forwards the query to upstream servers and caches the result
func (d *DNSForwarder) Resolve(host string) ([]net.IP, error) {
	// Check cache first (Read Lock)
	d.mu.RLock()
	if ips, ok := d.cache[host]; ok {
		d.mu.RUnlock()
		return ips, nil
	}
	d.mu.RUnlock()

	// If not in cache, query upstreams
	var allIPs []net.IP
	var err error

	// Try each upstream server
	for _, server := range d.upstream {
		ips, err := net.LookupIP(host)
		if err != nil {
			continue
		}
		allIPs = append(allIPs, ips...)
	}

	// If we found nothing, return error
	if len(allIPs) == 0 {
		return nil, fmt.Errorf("no records found for %s", host)
	}

	// Store in cache (Write Lock)
	d.mu.Lock()
	d.cache[host] = allIPs
	d.mu.Unlock()

	return allIPs, nil
}

// GetCached returns the cached IPs for a host without querying upstream
func (d *DNSForwarder) GetCached(host string) ([]net.IP, bool) {
	d.mu.RLock()
	defer d.mu.RUnlock()
	ips, ok := d.cache[host]
	return ips, ok
