// This function handles the logic: Case-insensitive search, partial matching, and sorting by relevance.
const searchHotels = async (query) => {
  if (!query || query.length < 2) return [];

  // We use ILIKE for case-insensitive partial matching
  // We escape the query to prevent SQL injection
  const escapedQuery = query.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&');
  const searchPattern = `%${escapedQuery}%`;

  const queryText = `
    SELECT id, name, city, country, rating 
    FROM hotels 
    WHERE name ILIKE $1 
    ORDER BY name ASC 
    LIMIT 10
  `;

  const client = await pool.connect();
  try {
    const result = await client.query(queryText, [searchPattern]);
    return result.rows;
  } finally {
    client.release();
  }
};

// 2. API Endpoint
